/bin/bash -lc "node --input-type=module <<'NODE'
const base = 'http://localhost:3100/'
let cookie = ''
for (const expected of ['on', 'off']) {
  const page = await fetch(base, { headers: cookie ? { cookie } : {} })
  const html = await page.text()
  const field = html.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)?.[1]
  if (!field) throw new Error('"'Server Action form field missing')
  const form = new FormData()
  form.append(field, '')
  const response = await fetch(base, {
    method: 'POST',
    body: form,
    headers: cookie ? { cookie } : {},
    redirect: 'manual',
  })
  const location = response.headers.get('location')
  const setCookie = response.headers.get('set-cookie')
  if ("'!setCookie?.includes(`notifications-enabled=${expected}`)) {
    throw new Error(`Expected ${expected} cookie; got ${setCookie}`)
  }
  if (location && new URL(location, base).pathname !== '"'/') {
    throw new Error("'`Unexpected destination: ${location}`)
  }
  cookie = setCookie.split('"';')[0]
  const updated = await (await fetch(base, { headers: { cookie } })).text()
  if ("'!updated.includes(`Notifications are <!-- -->${expected}`)) {
    throw new Error(`Page did not show notifications ${expected}`)
  }
  console.log(`Toggle ${expected}: POST ${response.status}, location ${location ?? '"'none'}, page updated"'`)
}
NODE'

